<template>
  <div class="catalog-page">
    <SiteHeader />
    <main>
      <section class="catalog-hero"><p class="eyebrow">Catálogo Kraken / 2026</p></section>
      <section class="catalog-content"><aside class="filters"><div class="filter-heading"><h2>Categorías</h2><span>{{ filteredProducts.length }} productos</span></div><button v-for="category in categories" :key="category" :class="{ active: selectedCategory === category }" @click="selectedCategory = category">{{ category }} <span>{{ categoryCount(category) }}</span></button><div class="filter-divider" /><h2>Filtrar por precio</h2><label class="price-label">Hasta {{ formatPrice(maxPrice) }}<input v-model.number="maxPrice" type="range" min="0" :max="catalogMaxPrice" step="5000" /></label><button class="reset-filter" @click="resetFilters">Restablecer filtros</button></aside><div class="products-area"><div class="products-toolbar"><label><Search :size="17" /><input v-model="searchQuery" type="search" placeholder="Buscar producto..." /></label><div><span>Ordenar por</span><select v-model="sortOrder"><option value="featured">Destacados</option><option value="low">Precio menor</option><option value="high">Precio mayor</option></select></div></div><div class="product-grid"><article v-for="product in filteredProducts" :key="product.code" class="product-card"><NuxtLink class="product-image" :to="`/productos/${product.slug}`"><img :src="product.image" :alt="product.name" loading="lazy" /><span>{{ product.code }}</span><span class="product-open"><ArrowUpRight :size="18" /></span></NuxtLink><div class="product-details"><small>{{ product.description }}</small><h3>{{ product.name }}</h3><strong>{{ formatPriceRange(product) }}</strong><button class="add-button" @click.stop="addProduct(product)">Agregar al carrito <ShoppingCart :size="15" /></button></div></article><p v-if="!filteredProducts.length" class="no-products">No encontramos productos con esos filtros.</p></div></div></section>
    </main>
  </div>
</template>
<script setup lang="ts">
import { ArrowUpRight, Search, ShoppingCart } from "lucide-vue-next";
import type { CatalogProduct } from "../../data/products";
const route = useRoute(); const { data: productData } = await useFetch<CatalogProduct[]>("/api/products"); const products = computed(() => productData.value || []); const { addToQuote } = useQuoteCart(); const searchQuery = ref(""); const requestedCategory = computed(() => route.query.categoria === "racks" ? "Racks metálicos" : "Todos"); const selectedCategory = ref(requestedCategory.value); const catalogMaxPrice = computed(() => products.value.reduce((maximum, product) => Math.max(maximum, product.priceFrom), 0));
const maxPrice = ref(catalogMaxPrice.value);
watch(catalogMaxPrice, (maximum, previousMaximum) => {
  if (maxPrice.value === previousMaximum || maxPrice.value > maximum) {
    maxPrice.value = maximum;
  }
}); const sortOrder = ref("featured"); const allCategories = ["Todos", "Racks metálicos", "Estanterías metálicas", "Góndolas", "Soluciones especiales"]; const categories = computed(() => requestedCategory.value === "Todos" ? allCategories : [requestedCategory.value]); const formatPrice = (value: number) => value ? `$ ${value.toLocaleString("es-AR")}` : "A cotizar"; const formatPriceRange = (product: CatalogProduct) => product.priceFrom ? `${formatPrice(product.priceFrom)} - ${formatPrice(product.priceTo)} + IVA` : "A cotizar + IVA"; const filteredProducts = computed(() => products.value.filter((product) => (requestedCategory.value === "Todos" || product.category === requestedCategory.value) && (selectedCategory.value === "Todos" || product.category === selectedCategory.value) && product.priceFrom <= maxPrice.value && product.name.toLowerCase().includes(searchQuery.value.toLowerCase())).sort((a, b) => sortOrder.value === "low" ? a.price - b.price : sortOrder.value === "high" ? b.price - a.price : 0)); const categoryCount = (category: string) => category === "Todos" ? products.value.length : products.value.filter((product) => product.category === category).length; function addProduct(product: CatalogProduct) { addToQuote({ name: product.name, price: product.priceFrom, details: product.description }); } function resetFilters() { selectedCategory.value = requestedCategory.value; maxPrice.value = catalogMaxPrice.value; searchQuery.value = ""; sortOrder.value = "featured"; }
useHead({ title: "Catálogo | Kraken" });
</script>
<style scoped>
