ns:repeat(3,minmax(0,1fr));gap:16px}.product-card{overflow:hidden;border:1px solid var(--line);background:var(--surface);transition:.3s}.product-card:hover{border-color:var(--red-bright);transform:translateY(-5px)}.product-image{position:relative;display:block;height:245px;overflow:hidden;background:#e5e5e5}.product-image img{width:100%;height:100%;object-fit:cover;filter:saturate(.75) contrast(1.05);transition:transform .5s}.product-card:hover img{transform:scale(1.06)}.product-image>span:first-of-type{position:absolute;top:13px;left:13px;padding:5px 7px;color:#fff;background:rgba(15,15,18,.78);font:10px "DM Mono"}.product-open{position:absolute;right:13px;bottom:13px;display:grid;width:38px;height:38px;place-items:center;color:#fff;background:var(--red)}.product-details{display:grid;gap:12px;padding:18px}.product-details small{color:var(--muted);font:10px "DM Mono";text-transform:uppercase}.product-details h3{min-height:43px;margin:0;font-size:16px;line-height:1.3}.product-details strong{font-size:12px}.add-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;color:#fff;border:0;background:var(--red);cursor:pointer;font-size:12px;font-weight:600}.add-button:hover{background:var(--red-bright)}.no-products{grid-column:1/-1;padding:60px 0;color:var(--muted);text-align:center}@media(max-width:900px){.catalog-content{grid-template-columns:190px 1fr}.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.catalog-hero{padding-top:55px}.catalog-content{display:block;padding-top:25px}.filters{margin-bottom:38px}.filter-divider,.filters h2:not(.filter-heading h2),.price-label,.reset-filter{display:none}.filters>button{display:inline-flex;width:auto;margin-right:18px;padding:0 0 10px}.products-toolbar{align-items:stretch;flex-direction:column;gap:16px}.products-toolbar label{width:100%}.products-toolbar>div{display:flex;justify-content:space-between}.product-grid{grid-template-columns:1fr}.product-image{height:min(72vw,300px)}}
</style>
